const input = $input.first().json ?? {};
const topic = input.topic ?? null;
const product = input.product ?? {};
const variants = Array.isArray(product.variants) ? product.variants : [];

return [{
  json: {
    topic,
    product,
    product_id: product.id ?? null,
    title: product.title ?? null,
    product_type: product.product_type ?? null,
    variant_count: variants.length,
    skus: variants.map((v) => v.sku).filter(Boolean)
  }
}];

const input = $input.first().json ?? {};
const errors = [];

const SUPPORTED_TOPICS = ['products/create', 'products/update', 'products/delete'];

if (!input.topic) errors.push('missing_topic');
else if (!SUPPORTED_TOPICS.includes(input.topic)) errors.push('unsupported_topic');

if (!input.product_id) errors.push('missing_product_id');

// Cambio de plan (2026-08-13): ya NO se exige SKU para aceptar el producto -- se
// guardan todas las variantes tengan o no SKU (ver Build_Catalog_Entries y
// 'Subflow: Upsert Qdrant Point', que usa variant_id como llave alterna sin SKU).

return [{
  json: {
    ...input,
    contract_errors: errors,
    contract_is_valid: errors.length === 0
  }
}];

const input = $input.first().json ?? {};

return [{
  json: {
    success: false,
    stage: 'input_validation',
    errors: input.contract_errors ?? ['unknown_validation_error'],
    topic: input.topic ?? null,
    product_id: input.product_id ?? null
  }
}];

const product = $('Route_Product_Action').item.json.product;
const images = $json ?? {};
const collectionTitles = $('Call_Get_Product_Collections').item.json.collection_titles ?? [];
const variants = Array.isArray(product.variants) ? product.variants : [];
// Cambio de plan (2026-08-13): se incluyen TODAS las variantes, tengan o no SKU.
// El id deterministico en 'Subflow: Upsert Qdrant Point' se calcula SIEMPRE a partir de
// variant_id (nunca del SKU) -- por eso variant_id siempre va en el payload. El SKU (si
// existe) y el color se guardan aqui como datos del payload, no como llave de identidad.
const items = variants.length > 0 ? variants : [{ sku: null, price: null, id: null, inventory_quantity: null, option1: null, title: null }];

const description = product.body_html
  ? String(product.body_html).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim()
  : null;

// Cambio (2026-08-26, ejecuciones 95400/95401): se agrega 'qdrant_written_at' (timestamp
// de ESTA ejecucion, no un campo de Shopify) al payload persistido. Sirve como guardia
// contra la condicion de carrera de Find_Orphaned_Variants -- ver la nota en ese nodo.
const eventTimestamp = new Date().toISOString();

// Cambio (2026-08-25): se agrega 'collections' al payload persistido, tomado del
// resultado de 'Subflow: Get Shopify Product Collections' (llamada GraphQL adicional,
// ya que Shopify no manda las collections de un producto en el webhook). Reemplaza a
// product_type como fuente de 'categoria' en la busqueda (Catalogo Qdrant (DEV)) --
// product_type se mantiene en el payload sin cambios, solo deja de ser lo que se usa
// para categoria.
// Cambio (2026-08-19): se agrega 'descripcion' al payload persistido (antes solo se usaba
// para armar el 'text' del embedding, nunca se guardaba en Qdrant). Preparacion para cuando
// se adapte Agente Asesor a leer el esquema plano nuevo -- no cambia nada de la logica de
// escritura/limpieza existente, solo agrega este campo.
// Cambio (2026-09-07): dual-write de compatibilidad. Se agrega un espejo del esquema
// viejo (pageContent + metadata.{sku,titulo,categoria,precio,stock,descripcion,Color})
// DENTRO del mismo payload plano, sin quitar ni renombrar ningun campo existente --
// 'Catalogo Qdrant (DEV)' hoy todavia lee item.payload.metadata.* (no se ha migrado su
// parser al esquema plano) y el equipo pidio no tocar ese flujo hasta terminar de probar
// el resto del pipeline. 'categoria' se deriva de collections[0] en mayusculas (misma
// convencion que usaba la columna curada del Sheet viejo); si no hay ninguna collection
// todavia, queda null. product_id/variant_id/main_image_url/variant_image_url NUNCA se
// tocan -- siguen en el mismo lugar de siempre en el payload plano.
const categoriaMirror = (Array.isArray(collectionTitles) && collectionTitles.length > 0 && collectionTitles[0])
  ? String(collectionTitles[0]).toUpperCase()
  : null;

return items.map((variant) => ({
  json: {
    sku: variant.sku ?? null,
    text: [product.title, product.product_type, description].filter(Boolean).join(' - '),
    payload: {
      product_id: product.id,
      title: product.title,
      product_type: product.product_type,
      price: variant.price ?? null,
      inventory: variant.inventory_quantity ?? null,
      variant_id: variant.id ?? null,
      sku: variant.sku ?? null,
      color: variant.option1 ?? variant.title ?? null,
      descripcion: description,
      collections: collectionTitles,
      main_image_url: images.main_image_url ?? null,
      variant_image_url: (images.variant_images && variant.id) ? (images.variant_images[variant.id] ?? null) : null,
      qdrant_written_at: eventTimestamp,
      pageContent: product.title ?? null,
      metadata: {
        sku: variant.sku ?? null,
        titulo: product.title ?? null,
        categoria: categoriaMirror,
        precio: variant.price ?? null,
        stock: variant.inventory_quantity ?? null,
        descripcion: description,
        Color: variant.option1 ?? variant.title ?? null
      }
    }
  }
}));

// Call_Generate_Embedding ahora corre en modo 'each' (una vez por variante), asi que
// llegan tantos items aqui como variantes con SKU se hayan construido en Build_Catalog_Entries.
// Se emparejan por indice (mismo orden de entrada/salida que garantiza el modo 'each').
const entries = $('Build_Catalog_Entries').all();
return $input.all().map((item, i) => ({
  json: {
    sku: entries[i].json.sku,
    payload: entries[i].json.payload,
    vector: item.json.vector
  }
}));

// Call_Upsert_Qdrant_Point ahora corre en modo 'each' (una vez por variante). Se
// emparejan por indice con Merge_Embedding_With_Payload para reportar el sku correcto
// de cada variante upserteada (antes se reportaba un solo sku fijo, siempre el mismo).
const merged = $('Merge_Embedding_With_Payload').all();
return $input.all().map((item, i) => ({
  json: {
    success: true,
    action: 'upserted',
    sku: merged[i]?.json?.sku ?? null,
    product_id: $('Route_Product_Action').item.json.product_id
  }
}));

return [{
  json: {
    product_id: String($('Route_Product_Action').item.json.product_id)
  }
}];

return [{
  json: {
    success: true,
    action: 'deleted',
    product_id: $('Route_Product_Action').item.json.product_id
  }
}];

// Corre una sola vez por evento (sin importar cuantas variantes se hayan
// upserteado arriba), para no repetir la consulta/limpieza de huerfanos N veces.
return [{
  json: {
    product_id: $('Route_Product_Action').item.json.product_id
  }
}];

