const scrollResponse = $input.first().json ?? {};
const existingPoints = Array.isArray(scrollResponse.result?.points) ? scrollResponse.result.points : [];

const currentEntries = $('Build_Catalog_Entries').all();
const currentVariantIds = currentEntries
  .map((item) => item.json?.payload?.variant_id)
  .filter((id) => id !== null && id !== undefined);
const currentSet = new Set(currentVariantIds.map(String));

// Timestamp de ESTA ejecucion (asignado en Build_Catalog_Entries, mismo valor para
// todas las variantes de este evento). Se usa como guardia de carrera abajo.
const eventTimestamp = currentEntries[0]?.json?.payload?.qdrant_written_at ?? null;

// Fix (2026-08-26, ejecuciones 95400/95401): dos eventos products/update casi
// simultaneos para el MISMO producto (Shopify recreo una variante -- id nuevo -- al
// agregarle/quitarle el SKU, y disparo dos webhooks segundos aparte) causaban que la
// limpieza de huerfanos de cada evento borrara la variante que el OTRO evento (mas
// nuevo) ya habia escrito -- terminando con el producto en CERO puntos en Qdrant pese
// a tener una variante activa real. Causa: cada evento solo conoce su propio payload
// (viejo o nuevo) y comparaba contra el estado completo de Qdrant sin saber si un punto
// que no reconoce es genuinamente huerfano o fue escrito por un evento mas reciente que
// llego casi al mismo tiempo.
// Fix: cada punto guarda su propio 'qdrant_written_at' (seccion de arriba). Aqui, un
// punto NUNCA se marca huerfano si su 'qdrant_written_at' es MAS RECIENTE que el de
// este evento -- eso significa que un evento mas nuevo ya lo escribio despues de que
// este evento arranco, y no debe ser borrado por uno mas viejo. Los puntos genuinamente
// huerfanos (mas viejos que este evento, o sin el campo -- puntos de antes de este fix)
// se siguen borrando igual que antes.
const orphanedVariantIds = [...new Set(
  existingPoints
    .filter((p) => {
      const pointTimestamp = p.payload?.qdrant_written_at;
      if (eventTimestamp && pointTimestamp && pointTimestamp > eventTimestamp) {
        return false; // escrito por un evento mas nuevo -- no tocar
      }
      return true;
    })
    .map((p) => p.payload?.variant_id)
    .filter((id) => id !== null && id !== undefined && !currentSet.has(String(id)))
)];

return [{
  json: {
    product_id: $('Route_Product_Action').item.json.product_id,
    orphaned_variant_ids: orphanedVariantIds
  }
}];

